func newOperationsTestDB(t *testing.T) *store.DB {
	t.Helper()
	dsn := strings.TrimSpace(os.Getenv("MOYRO_TEST_POSTGRES_DSN"))
	if dsn == "" {
		t.Skip("MOYRO_TEST_POSTGRES_DSN is not set")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	adminPool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	if err := adminPool.Ping(ctx); err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	schemaName := "moyro_operations_" + strings.ReplaceAll(uuid.NewString(), "-", "")
	quotedSchema := pgx.Identifier{schemaName}.Sanitize()
	if _, err := adminPool.Exec(ctx, "CREATE SCHEMA "+quotedSchema); err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	config, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	config.ConnConfig.RuntimeParams["search_path"] = quotedSchema
	config.MaxConns = 4
	testPool, err := pgxpool.NewWithConfig(ctx, config)
	if err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	t.Cleanup(func() {
		testPool.Close()
		cleanupCtx, cleanupCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cleanupCancel()
		if _, err := adminPool.Exec(cleanupCtx, "DROP SCHEMA "+quotedSchema+" CASCADE"); err != nil {
			t.Errorf("drop operations schema: %v", err)
		}
		adminPool.Close()
	})
	return &store.DB{Pool: testPool}
}
// Package postacks implements Mattermost's "post acknowledgements" feature:
// when a sender wants explicit confirmation that recipients have read an
// important message, they tag the post with `requested_ack: true` (in
// `posts.props`), and recipients click an "Ack" button to record one row per
// (post_id, user_id) in this package's table. The list endpoint hydrates a
// post-ack badge on the recipient's UI.
package postacks

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/hkjang/moyro/server/internal/store"
)

// Ack is one acknowledgement row. We intentionally leak the wire-shape names
// (acknowledged_at) used by the official Mattermost desktop client so the
// JSON marshals straight through without a separate adapter.
type Ack struct {
	PostID         string `json:"post_id"`
	UserID         string `json:"user_id"`
	AcknowledgedAt int64  `json:"acknowledged_at"`
}

type Service struct{ db *store.DB }

func New(db *store.DB) *Service { return &Service{db: db} }

// Save records an ack. Idempotent (re-acking the same post just touches
// ack_at). Returns the persisted row so the handler can broadcast a WS event
// with a stable timestamp.
func (s *Service) Save(ctx context.Context, postID, userID string) (*Ack, error) {
	if postID == "" || userID == "" {
		return nil, errors.New("post_id and user_id required")
	}
	now := time.Now().UnixMilli()
	_, err := s.db.Pool.Exec(ctx, `
		INSERT INTO post_acknowledgements (post_id, user_id, ack_at)
		VALUES ($1, $2, $3)
		ON CONFLICT (post_id, user_id) DO UPDATE SET ack_at = EXCLUDED.ack_at
	`, postID, userID, now)
	if err != nil {
		return nil, err
	}
	return &Ack{PostID: postID, UserID: userID, AcknowledgedAt: now}, nil
}

// Delete removes an ack. Returns (true, nil) if the row was actually deleted,
// (false, nil) if the user had never ack'd this post — both are 200-OK
// outcomes for the caller; the boolean is just for audit-log fidelity.
func (s *Service) Delete(ctx context.Context, postID, userID string) (bool, error) {
	tag, err := s.db.Pool.Exec(ctx, `
		DELETE FROM post_acknowledgements WHERE post_id=$1 AND user_id=$2
	`, postID, userID)
	if err != nil {
		return false, err
	}
	return tag.RowsAffected() > 0, nil
}

// ListForPost returns every ack for the given post, oldest first so the UI
// can render "ack'd by Alice 2 minutes ago, then Bob 30s ago".
func (s *Service) ListForPost(ctx context.Context, postID string) ([]Ack, error) {
	rows, err := s.db.Pool.Query(ctx, `
		SELECT post_id, user_id, ack_at FROM post_acknowledgements
		WHERE post_id=$1 ORDER BY ack_at ASC
	`, postID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []Ack{}
	for rows.Next() {
		var a Ack
		if err := rows.Scan(&a.PostID, &a.UserID, &a.AcknowledgedAt); err != nil {
			return nil, err
		}
		out = append(out, a)
	}
	return out, rows.Err()
}

// ListForPosts is a bulk lookup keyed by post_id → []Ack so the post-stream
// hydration only does one round-trip. Cap input at 200 ids.
func (s *Service) ListForPosts(ctx context.Context, postIDs []string) (map[string][]Ack, error) {
	out := map[string][]Ack{}
	if len(postIDs) == 0 {
		return out, nil
	}
	if len(postIDs) > 200 {
		postIDs = postIDs[:200]
	}
	rows, err := s.db.Pool.Query(ctx, `
		SELECT post_id, user_id, ack_at FROM post_acknowledgements
		WHERE post_id = ANY($1) ORDER BY post_id, ack_at ASC
	`, postIDs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var a Ack
		if err := rows.Scan(&a.PostID, &a.UserID, &a.AcknowledgedAt); err != nil {
			return nil, err
		}
		out[a.PostID] = append(out[a.PostID], a)
	}
	return out, rows.Err()
}

// Get returns one ack row, or (nil, nil) if the user hasn't ack'd. Used by
// the handler to short-circuit DELETE before touching the table.
func (s *Service) Get(ctx context.Context, postID, userID string) (*Ack, error) {
	var a Ack
	err := s.db.Pool.QueryRow(ctx, `
		SELECT post_id, user_id, ack_at FROM post_acknowledgements
		WHERE post_id=$1 AND user_id=$2
	`, postID, userID).Scan(&a.PostID, &a.UserID, &a.AcknowledgedAt)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, nil
		}
		return nil, err
	}
	return &a, nil
}
// Package reminders implements post reminders. A user picks a post and a
// future time; when the time arrives a `reminder_fired` WS event is
// delivered to the owning user's sockets with a short excerpt and a deep
// link back to the channel.
//
// Same claim discipline as the scheduled-posts worker: delivered_at=0 is
// pending, flip to -1 during dispatch, then stamp to now on success. A
// dropped delivery isn't catastrophic (user can see the post already in
// their sidebar badge) so we don't retry failed claims aggressively.
package reminders

import (
	"context"
	"time"

	"github.com/google/uuid"
	"github.com/hkjang/moyro/server/internal/store"
)

type Reminder struct {
	ID          string `json:"id"`
	UserID      string `json:"user_id"`
	PostID      string `json:"post_id"`
	RemindAt    int64  `json:"remind_at"`
	CreateAt    int64  `json:"create_at"`
	DeliveredAt int64  `json:"delivered_at"`
}

type Service struct{ db *store.DB }

func New(db *store.DB) *Service { return &Service{db: db} }

// Create enqueues a reminder. Caller validates the user can see the post
// (channel membership) up-front.
func (s *Service) Create(ctx context.Context, userID, postID string, remindAt int64) (*Reminder, error) {
	r := &Reminder{
		ID:       uuid.NewString(),
		UserID:   userID,
		PostID:   postID,
		RemindAt: remindAt,
		CreateAt: time.Now().UnixMilli(),
	}
	_, err := s.db.Pool.Exec(ctx, `
		INSERT INTO post_reminders (id, user_id, post_id, remind_at, create_at)
		VALUES ($1, $2, $3, $4, $5)
	`, r.ID, r.UserID, r.PostID, r.RemindAt, r.CreateAt)
	if err != nil {
		return nil, err
	}
	return r, nil
}

// ListPending returns reminders that haven't fired yet for the caller.
func (s *Service) ListPending(ctx context.Context, userID string) ([]*Reminder, error) {
	rows, err := s.db.Pool.Query(ctx, `
		SELECT id, user_id, post_id, remind_at, create_at, delivered_at
		FROM post_reminders
		WHERE user_id=$1 AND delivered_at = 0
		ORDER BY remind_at ASC
	`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []*Reminder{}
	for rows.Next() {
		var r Reminder
